def gc_content(seq):
    gc = seq.count("G") + seq.count("C")
    return gc / len(seq)

print(gc_content("ATGC"))

def dilute(c, factor=10):
    return c / factor

print(dilute(50), dilute(50, 5), dilute(factor=2, c=50))

